  "prior_work": {
    "already_answered": "partly",
    "cited": [
      "FAM:SF34",
      "FAM:SF26",
      "FAM:SF-TMP-018"
    ],
    "summary": "Prior work shows that opponent lineup changes produce detectable but small shot-mix shifts (SF34) and that play-type-based predictions often yield nulls (SF26, SF-TMP-018). No prior study directly tests whether own-lineup changes cause measurable shot-mix differences, but these findings indicate that power, confounding, and measurement reliability must be carefully handled."
  },
  "risks": [
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "Even with three full seasons, some shot-type categories may have low frequency, and effect sizes may be small (as in SF34). A composite test will mitigate this, but power should be calculated beforehand."
    },
    {
      "code": "CONFOUNDING",
      "text": "Substitutions often co-occur for both teams and are correlated with game situation (score, period, rest). Failure to control for opponent lineup, game clock, and score could bias estimates."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "If many individual shot types or lineup combinations are tested separately, multiplicity will inflate false positives. A pre-registered global test addresses this."
    },
    {
      "code": "RTM_SELECTION",
      "text": "Coaches may insert or remove players after extreme events (e.g., a bad stretch), causing regression toward the mean that could be mistaken for a lineup effect."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "The derived play-type categories (e.g., 'drive', 'post-up', 'spot-up') may be mis-labelled, especially if based on heuristics. Prior studies flagged low measurement reliability as a limiting factor."
    },
    {
      "code": "LEAKAGE_LOOKAHEAD",
      "text": "Lineup membership must be determined only from information available at the time of the possession; using future rotation data would induce lookahead bias."
    },
    {
      "code": "BASE_RATE",
      "text": "Rare shot types (e.g., alley-oops, post-ups) will have very low per-possession rates, making their estimated changes noisy and unreliable."
    }
  ],
  "predicted_outcome": {
    "supported": 0.5,
    "rejected": 0.3,
    "untestable": 0.0,
    "artifact": 0.05,
    "uncertain": 0.15
  },
  "decision": "proceed_with_changes",
  "design": {
    "estimand": "The average effect of a change in the offensive five (substitution) on the multinomial distribution of shot types (e.g., rim, short mid-range, long mid-range, non-corner 3, corner 3) or play types (e.g., isolation, pick-and-roll, off-screen, transition, post-up), measured per possession.",
    "unit": "one offensive possession",
    "sample": "All regular-season and playoff possessions from the 2022-23 through 2024-25 NBA seasons, excluding garbage time (defined as Q4 with >20-point differential and <5:00 remaining), end-of-quarter heaves, and possessions where the offensive or defensive lineup is ambiguous due to simultaneous substitutions.",
    "power": "Power analysis will be conducted using the outcome standard errors observed in SF34 for comparable shot-type proportions. With ~1M possessions per season and a focus on a composite multinomial test, the study will have >80% power to detect a shift of 0.5 percentage points in any single shot-type category (e.g., 3PA share) at alpha=0.05, assuming baseline rates of 25-40%. If preliminary power analysis shows insufficient sensitivity, the analysis will be restricted to high-frequency categories (rim, mid-range, 3pt) and the largest plausible substitution types (e.g., centre-for-centre vs. centre-for-guard swaps).",
    "controls": "Within-game and within-period fixed effects; indicator variables for 2-minute clock bins; score differential (lead/trail); opponent lineup characteristics (number of traditional bigs, number of guards); and indicator for whether the substitution was a timeout or end-of-quarter break. To address RTM, we will also include a control for the previous possession's outcome (points, shot type) and test for pre-trends.",
    "falsification": "1) Placebo test: Compare shot-mix changes in possessions immediately before the substitution (when the lineup is still the original one) to those after, expecting no difference if the substitution timing is unrelated to shot selection. 2) Close-match test: Among substitutions where the incoming and outgoing players share the same position and archetype (based on external clustering), the composite shift should be insignificantly different from zero. 3) Negative control: Repeat the analysis on a random, independent sample of non-substitution possession pairs to confirm that the detected shift is not an artefact of the differencing method.",
    "multiplicity": "A single composite hypothesis will be pre-registered: the multinomial distribution of shot types differs between possessions with the old and new offensive five. This will be tested via a likelihood-ratio test or chi-squared statistic. No separate per-category hypothesis tests will be used for the primary conclusion.",
    "decision_rule": "The design is declared to detect personnel effects if the composite test yields p < 0.05 (two-sided) and all three falsification criteria are satisfied (placebo test non-significant at p > 0.10, close-match test non-significant, negative control non-significant). If the composite test is non-significant, the design is considered unable to detect personnel effects with the current sample.",
    "data_version": "NBA 2022-23, 2023-24, 2024-25 play-by-play and derived play-type possessions as of 2026-11-02."
  }
}}

